{{ config(alias='leads_daily') }}

select
  cast(metric_time__day as date) as metric_time__day,
  campaign__campaign_name,
  campaign__channel,
  campaign__market,
  lead__country,
  leads
from (
  -- Join Standard Outputs
  -- Select: ['__leads', 'campaign__campaign_name', 'campaign__channel', 'campaign__market', 'lead__country', 'metric_time__day']
  -- Select: ['__leads', 'campaign__campaign_name', 'campaign__channel', 'campaign__market', 'lead__country', 'metric_time__day']
  -- Aggregate Inputs for Simple Metrics
  -- Compute Metrics via Expressions
  -- Write to DataTable
  SELECT
    subq_1.metric_time__day AS metric_time__day
    , subq_1.lead__country AS lead__country
    , campaigns_src_10000.channel AS campaign__channel
    , campaigns_src_10000.market AS campaign__market
    , campaigns_src_10000.name AS campaign__campaign_name
    , SUM(subq_1.__leads) AS leads
  FROM (
    -- Read Elements From Semantic Model 'leads'
    -- Metric Time Dimension 'created_date'
    SELECT
      TIMESTAMP_TRUNC(created_date, day) AS metric_time__day
      , campaign_id AS campaign
      , country AS lead__country
      , 1 AS __leads
    FROM {{ ref('slv_leads') }} leads_src_10000
  ) subq_1
  LEFT OUTER JOIN
    {{ ref('slv_campaigns') }} campaigns_src_10000
  ON
    subq_1.campaign = campaigns_src_10000.campaign_id
  GROUP BY
    metric_time__day
    , lead__country
    , campaign__channel
    , campaign__market
    , campaign__campaign_name
) as metricflow
